-- Pikul — full database setup for a fresh Neon project (generated by scripts/db-setup.mjs; do not edit by hand).
-- Contains: 001_accounts_billing.sql, 002_admin_console.sql, 003_admin_revamp.sql, 004_merchant_signup.sql, 005_device_sync.sql, 006_device_names.sql. Safe to run more than once.
-- Neon console → your project → SQL Editor → paste all of this → Run.
begin;

-- ===== 001_accounts_billing.sql =====
-- v0.14 accounts and trial (ADR-013). Neon Postgres. Payments were removed with Midtrans (ADR-015).
create table if not exists accounts (
  id uuid primary key,
  email text not null unique check (email = lower(email)),
  google_sub text unique,
  created_at timestamptz not null default now(),
  trial_ends_at timestamptz not null,
  paid_until timestamptz
);

create table if not exists login_codes (
  email text primary key,
  code_hash text not null,
  expires_at timestamptz not null,
  attempts int not null default 0,
  sent_at timestamptz not null
);

create table if not exists refresh_tokens (
  token_hash text primary key,
  account_id uuid not null references accounts(id) on delete cascade,
  expires_at timestamptz not null
);
create index if not exists refresh_tokens_account_idx on refresh_tokens(account_id);

-- ===== 002_admin_console.sql =====
-- v0.15 admin console: plans, promo campaigns, admin audit (ADR-014). Neon Postgres. Run after 001.
create table if not exists plans (
  id text primary key check (id ~ '^[a-z0-9][a-z0-9-]{1,23}$'),
  name text not null,
  amount integer not null check (amount between 1000 and 100000000),
  days integer not null check (days between 1 and 1095),
  note text not null default '',
  badge text not null default '',
  features jsonb not null default '[]'::jsonb,
  active boolean not null default true,
  sort integer not null default 0,
  updated_at timestamptz not null default now()
);

-- Seed = the v0.14 placeholder plans. Change them in /admin, not here.
insert into plans (id, name, amount, days, note, badge, features, sort) values
  ('monthly', 'Bulanan', 49000, 30, 'Lanjut setelah masa coba. Bayar dengan QRIS, VA, GoPay, atau ShopeePay.', '',
   '["Semua fitur di masa coba", "Perpanjang kapan saja, tanpa hari hilang", "Data tetap milik Anda"]', 10),
  ('yearly', 'Tahunan', 490000, 365, 'Hemat dua bulan dibanding bayar bulanan.', 'Hemat 2 bulan',
   '["Semua fitur di masa coba", "Sekali bayar untuk setahun", "Data tetap milik Anda"]', 20)
on conflict (id) do nothing;

create table if not exists campaigns (
  id uuid primary key,
  name text not null,
  title text not null,
  body text not null default '',
  image_url text,
  link_url text,
  cta_label text not null default '',
  show_on_landing boolean not null default true,
  show_in_app boolean not null default false,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  enabled boolean not null default false,
  archived boolean not null default false,
  plan_id text references plans(id),
  promo_amount integer check (promo_amount is null or promo_amount >= 1000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (ends_at > starts_at),
  check ((plan_id is null) = (promo_amount is null))
);
create index if not exists campaigns_live_idx on campaigns(starts_at desc) where not archived;

-- Uploaded banner images (PNG/JPEG/WebP, <= 500 KB), served at /api/public/images/<id>. R2 can replace this later.
create table if not exists images (
  id uuid primary key,
  mime text not null check (mime in ('image/png', 'image/jpeg', 'image/webp')),
  data_b64 text not null,
  created_at timestamptz not null default now()
);

create table if not exists admin_audit (
  id bigint generated always as identity primary key,
  at timestamptz not null default now(),
  email text not null,
  action text not null,
  target text not null,
  detail jsonb
);

-- ===== 003_admin_revamp.sql =====
-- v0.17 business console (ADR-020): payments ledger, trial grants, admin sessions, rate limits,
-- merchant daily totals, landing content, register pop-up placement. Neon Postgres. Run after 001 and 002.

alter table accounts add column if not exists last_seen_at timestamptz;

-- Manual subscription payments. Append-only: a wrong entry is cancelled (cancelled_at), never deleted.
create table if not exists payments (
  id uuid primary key,
  account_id uuid not null references accounts(id),
  plan_id text references plans(id),
  amount integer not null check (amount between 0 and 1000000000),
  days integer not null check (days between 1 and 1095),
  method text not null check (method in ('transfer', 'qris', 'ewallet', 'cash', 'other')),
  reference text not null default '',
  paid_on date not null,
  note text not null default '',
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  prev_paid_until timestamptz,
  recorded_at timestamptz not null default now(),
  recorded_by text not null,
  cancelled_at timestamptz,
  cancel_reason text,
  check (ends_at > starts_at),
  check ((cancelled_at is null) = (cancel_reason is null))
);
create index if not exists payments_account_idx on payments(account_id, recorded_at desc);
create index if not exists payments_paid_on_idx on payments(paid_on);

-- Free trial days given from the console.
create table if not exists account_grants (
  id uuid primary key,
  account_id uuid not null references accounts(id),
  days integer not null check (days between 1 and 60),
  reason text not null,
  prev_trial_ends_at timestamptz not null,
  new_trial_ends_at timestamptz not null,
  at timestamptz not null default now(),
  by text not null
);
create index if not exists account_grants_account_idx on account_grants(account_id, at desc);

-- Admin password sign-in (ADMIN_PASSWORD secret). Only the SHA-256 of the token is stored.
create table if not exists admin_sessions (
  token_hash text primary key,
  created_at timestamptz not null,
  expires_at timestamptz not null
);

-- Sliding-window counters: admin login failures (per IP and global) and merchant daily posts.
create table if not exists rate_events (
  key text not null,
  at timestamptz not null
);
create index if not exists rate_events_key_at_idx on rate_events(key, at);

-- One row per merchant account per business date: totals only (no receipts, items, customers or staff).
create table if not exists merchant_daily (
  account_id uuid not null references accounts(id),
  business_date date not null,
  transactions integer not null,
  gross bigint not null,
  discounts bigint not null,
  refunds bigint not null,
  net bigint not null,
  void_count integer not null,
  void_amount bigint not null,
  items_sold numeric not null,
  cash_tx integer not null default 0, cash_gross bigint not null default 0, cash_refunds bigint not null default 0,
  qris_tx integer not null default 0, qris_gross bigint not null default 0, qris_refunds bigint not null default 0,
  transfer_tx integer not null default 0, transfer_gross bigint not null default 0, transfer_refunds bigint not null default 0,
  ewallet_tx integer not null default 0, ewallet_gross bigint not null default 0, ewallet_refunds bigint not null default 0,
  other_tx integer not null default 0, other_gross bigint not null default 0, other_refunds bigint not null default 0,
  modes jsonb not null default '[]'::jsonb,
  hours jsonb not null default '[]'::jsonb,
  app_version text not null default '',
  computed_at timestamptz not null,
  received_at timestamptz not null,
  primary key (account_id, business_date)
);
create index if not exists merchant_daily_date_idx on merchant_daily(business_date);

alter table campaigns add column if not exists show_on_register boolean not null default false;

-- Landing page text edited in the console. One row; missing = the built-in text in the page.
create table if not exists site_content (
  id integer primary key check (id = 1),
  content jsonb not null,
  updated_at timestamptz not null default now()
);

-- ===== 004_merchant_signup.sql =====
-- v0.18 merchant sign-up with password and profile (ADR-023). Neon Postgres. Run after 001, 002 and 003.
-- The profile is what the merchant typed on the sign-up page; the admin console shows it in Merchant.

alter table accounts add column if not exists password_hash text;
alter table accounts add column if not exists password_changed_at timestamptz;
alter table accounts add column if not exists owner_name text not null default '';
alter table accounts add column if not exists store_name text not null default '';
alter table accounts add column if not exists phone text not null default '';
alter table accounts add column if not exists city text not null default '';

-- Admin search by store or owner name stays fast enough as a sequential scan for thousands of rows; no index yet.
-- rate_events grows with failed sign-ins; old rows can be removed any time:
--   delete from rate_events where at < now() - interval '1 day';

-- ===== 005_device_sync.sql =====
-- v0.19 device sync (ADR-025). Neon Postgres. Run after 001–004.
-- One store per account; every synced record is stored as the device's JSON, last write wins by updatedAt.

create table if not exists account_store (
  account_id uuid primary key references accounts(id) on delete cascade,
  store_id uuid not null,
  bound_at timestamptz not null default now(),
  replaced_at timestamptz
);

create sequence if not exists sync_seq;

create table if not exists sync_records (
  account_id uuid not null references accounts(id) on delete cascade,
  tbl text not null,
  id uuid not null,
  data jsonb not null,
  updated_at timestamptz not null,
  device_id text not null,
  seq bigint not null default nextval('sync_seq'),
  changed_at timestamptz not null default now(),
  primary key (account_id, tbl, id)
);
-- Pull reads "everything after my cursor" for one account.
create index if not exists sync_records_pull_idx on sync_records(account_id, seq);

create table if not exists sync_devices (
  account_id uuid not null references accounts(id) on delete cascade,
  device_id text not null,
  name text not null default '',
  receipt_code text not null default '',
  first_seen timestamptz not null default now(),
  last_seen timestamptz not null default now(),
  app_version text not null default '',
  primary key (account_id, device_id)
);

-- ===== 006_device_names.sql =====
-- v0.19.7 recognisable devices. Neon Postgres. Run after 005.
-- Each device reports its browser and system ("Chrome · Android") and whether it runs in a private window,
-- so the owner can tell devices apart in Pengaturan → Sinkronisasi and remove old incognito ones.

alter table sync_devices add column if not exists auto_name text not null default '';
alter table sync_devices add column if not exists private_mode boolean not null default false;

commit;

-- Check: should list accounts, account_grants, admin_audit, admin_sessions, campaigns, images, login_codes,
-- merchant_daily, payments, plans, rate_events, refresh_tokens, site_content, account_store, sync_devices, sync_records.
select table_name from information_schema.tables where table_schema = 'public' order by table_name;
